import type { Metadata } from "next";
import { SITE_DESCRIPTION, SITE_NAME, SITE_TAGLINE } from "@/constants/site";

// Generated by app/opengraph-image.tsx. Named explicitly because a page that sets its own
// openGraph object loses the inherited file-based image.
const SHARE_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: `${SITE_NAME}: ${SITE_TAGLINE}` };

/**
 * Page metadata with matching sharing tags. Next replaces (not merges) the root openGraph and
 * twitter objects, so each page restates them with its own title, description and URL.
 */
export const pageMetadata = ({
    title,
    description = SITE_DESCRIPTION,
    path,
}: {
    /** Page name; the root layout's template adds " · Flucks". Omit for the home page. */
    title?: string;
    description?: string;
    path: string;
}): Metadata => {
    const shareTitle = title ? `${title} · ${SITE_NAME}` : SITE_NAME;
    return {
        ...(title ? { title } : {}),
        description,
        alternates: { canonical: path },
        openGraph: {
            type: "website",
            siteName: SITE_NAME,
            locale: "en_IN",
            title: shareTitle,
            description,
            url: path,
            images: [SHARE_IMAGE],
        },
        twitter: { card: "summary_large_image", title: shareTitle, description, images: [SHARE_IMAGE] },
    };
};
